declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '6';
  if old_rule_count <> 1 then raise exception 'Expected 1 generated Book 3 lesson 6 rule, found %', old_rule_count; end if;
  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '6');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '6');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '6';
  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values ('Мединский курс (Том 3)', '6', 'اسْمَا الزَّمَانِ وَالْمَكَانِ (имена времени и места)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">اسْمَا الزَّمَانِ وَالْمَكَانِ</span> اسْمَانِ مَصُوغَانِ لِلدَّلَالَةِ عَلَى زَمَانِ الْفِعْلِ أَوْ مَكَانِهِ.</span><p class="rule-study-text">Имя времени обозначает время действия, а имя места — место действия.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يُصَاغَانِ مِنَ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى وَزْنَيْنِ: <span class="ar-tone-structure">مَفْعَلٌ</span> وَ<span class="ar-tone-structure">مَفْعِلٌ</span>.</span><p class="rule-study-text">Для простого трёхбуквенного глагола шарх устанавливает две основные модели.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Модель مَفْعَلٌ: конечно-слабый глагол</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ الزَّمَانِ أَوِ الْمَكَانِ</span><span class="rule-table-ru">имя времени или места</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَمَى</span><span class="rule-table-ru">он бросил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَرْمًى</span><span class="rule-table-ru">цель; место броска</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ نَاقِصٌ</span><span class="rule-table-ru">конечно-слабый глагол</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَقَى</span><span class="rule-table-ru">он защитил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَوْقًى</span><span class="rule-table-ru">место защиты</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ نَاقِصٌ</span><span class="rule-table-ru">конечно-слабый глагол</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">غَزَا</span><span class="rule-table-ru">он совершил поход</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَغْزًى</span><span class="rule-table-ru">цель; место или время похода</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ نَاقِصٌ</span><span class="rule-table-ru">конечно-слабый глагол</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَأَى</span><span class="rule-table-ru">он увидел</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَرْأًى</span><span class="rule-table-ru">вид; место видимости</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ نَاقِصٌ</span><span class="rule-table-ru">конечно-слабый глагол</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Модель مَفْعَلٌ: настоящая форма с фатхой или даммой на среднем корневом согласном</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедший глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущий глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">имя времени или места</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى وَالْأَصْلُ